import{_ as o,l as r,o as e,c as n,v as l,p,x as s,d as i,i as m,S as h}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"评测框架 lm-eval / OpenCompass","description":"","frontmatter":{"title":"评测框架 lm-eval / OpenCompass","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/eval-harness.md","filePath":"llm/eval-harness.md","lastUpdated":1789023840000}'),d={name:"llm/eval-harness.md"};function E(c,a,A,_,u,v){const t=r("Mermaid");return e(),n("div",null,[a[1]||(a[1]=l('<h1 id="评测框架-lm-eval-opencompass" tabindex="-1">评测框架 lm-eval / OpenCompass <a class="header-anchor" href="#评测框架-lm-eval-opencompass" aria-label="Permalink to &quot;评测框架 lm-eval / OpenCompass&quot;">​</a></h1><div class="epigraph"><p>分数是脚本的输出。没有冻结的任务注册表、模板与抽取器，排行榜只是各实验室私有管道的合影。</p><footer>—— Gao 等 EleutherAI lm-evaluation-harness；OpenCompass 作为并行实现传统</footer></div><p><a href="/llm/multilingual-benchmarks">上一课</a>把译文卷与原生卷分列，禁止用单标量平均淹没尾部语种；分词碎片、拒答对齐、污染是三类不同的跌分。缺口是工程。这些选择必须落在同一份可版本化的代码里，否则每个仓库一份 <code>eval.py</code>，细差累积成不可复现的「领先 1.2 分」。本课写 lm-eval 与 OpenCompass 如何把任务登记成对象。不重拆多语言跌分。后课饱和默认：你比的是同一 harness 版本上的曲线，不是网页截图。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>每个模型仓库都有一份 <code>eval.py</code>。选项是否归一、GSM8K 抽哪一行、聊天模板从哪来，细差累积成不可复现的「领先 1.2 分」。框架的工作是把任务登记成对象：数据集路径、提示构造、请求类型（loglik / generate）、后处理、指标。EleutherAI 的 lm-evaluation-harness 把这件事做成社区默认；OpenCompass 在中文任务、模型适配与并行后端上给出另一套登记表。二者不是同一份数字，不能混表。</p><p>框架还会把错误藏进默认值：某任务默认 0-shot 无模板，某任务默认 5-shot 带聊天。只报「用了 lm-eval」而不报提交哈希与任务配置，等于没报。</p><p><span class="marginnote">HELM 走另一条路：端到端场景、多指标、明确的场景卡。它更重、更慢，适合声明级审计。日常回归用 harness，发布卡用 HELM 或同等场景描述，不要让其中之一吞掉另一。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>最小可复现包：框架版本或 git SHA、任务列表与 few-shot、\\(n\\) 采样、生成超参、chat template 名、是否 apply 系统提示、随机种子（见<a href="/llm/eval-variance-seed">评测方差</a>）。输出应保留 per-example 预测，以便事后换抽取器而不重跑模型。</p><p>新增任务：先写金标小集人工核对抽取器，再并入全量。禁止把私有提示调优写进「官方默认」。</p>',10)),(e(),p(h,null,{default:s(()=>[m(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20REG%5B%22%E4%BB%BB%E5%8A%A1%E6%B3%A8%E5%86%8C%E8%A1%A8%22%5D%20--%3E%20REQ%5B%22loglik%20%2F%20generate%20%E8%AF%B7%E6%B1%82%22%5D%0A%20%20REQ%20--%3E%20MODEL%5B%22%E6%A8%A1%E5%9E%8B%E9%80%82%E9%85%8D%E5%99%A8%22%5D%0A%20%20MODEL%20--%3E%20POST%5B%22%E6%8A%BD%E5%8F%96%E4%B8%8E%E6%8C%87%E6%A0%87%22%5D%0A%20%20POST%20--%3E%20TAB%5B%22%E5%B8%A6%E9%85%8D%E7%BD%AE%E5%93%88%E5%B8%8C%E7%9A%84%E8%A1%A8%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>适配器把「模型 API」收成统一请求：补全、对话、对数概率。差异发生在适配器——有的实现把 chat 包装在评测器外，有的在内。同一 harness、不同适配器，仍可差出格式课写过的那几个点。比较开源权重时，应固定适配器实现，而不是固定「都叫 lm-eval」。</p><p>并行与缓存必须不改随机性：请求顺序若影响批内数值（极少见但存在于非确定核），要锁种子与批大小。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>框架不解决污染、不解决饱和、不解决法官偏差。它只冻结仪器。下一课处理仪器还在走、但公开卷面已经没有刻度的情况。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>分数绑定框架版本、任务配置与适配器，三者写入报告。</li><li>lm-eval 与 OpenCompass 分表，禁止混成「开源评测分」。</li><li>保留逐题输出，抽取器才能后验迭代。</li><li>出处：Gao 等 lm-evaluation-harness；OpenCompass；Liang 等 HELM。</li></ul>',7))])}const C=o(d,[["render",E]]);export{B as __pageData,C as default};
